{{-- Restyled copy of Livewire's tailwind pagination view. The wire:click / scroll /
     dusk wiring is unchanged from the package; only classes and the phone layout differ. --}}
@php
if (! isset($scrollTo)) {
    $scrollTo = 'body';
}

$scrollIntoViewJsSnippet = ($scrollTo !== false)
    ? <<<JS
       (\$el.closest('{$scrollTo}') || document.querySelector('{$scrollTo}')).scrollIntoView()
    JS
    : '';

$pagerBase = 'relative inline-flex h-9 items-center justify-center rounded-md border px-3 text-sm font-medium';
$pagerIdle = 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50 active:bg-slate-100 focus:z-10 focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 transition-colors';
$pagerOff = 'cursor-default border-slate-200 bg-white text-slate-300';
@endphp

<div>
    @if ($paginator->hasPages())
        <nav role="navigation" aria-label="Pagination Navigation" class="flex items-center justify-between">
            <div class="flex flex-1 items-center justify-between gap-3 sm:hidden">
                <span>
                    @if ($paginator->onFirstPage())
                        <span class="{{ $pagerBase }} {{ $pagerOff }}">
                            {!! __('pagination.previous') !!}
                        </span>
                    @else
                        <button type="button" wire:click="previousPage('{{ $paginator->getPageName() }}')" x-on:click="{{ $scrollIntoViewJsSnippet }}" wire:loading.attr="disabled" dusk="previousPage{{ $paginator->getPageName() == 'page' ? '' : '.' . $paginator->getPageName() }}.before" class="{{ $pagerBase }} {{ $pagerIdle }}">
                            {!! __('pagination.previous') !!}
